var _markdown = "\n\n`CAudioEngine.h` · 全局 `AudioEngine`\n\n前端音效、电台、主音量。细粒度 `CAE*` 实体本页不展开。\n\n## 前端音效 [#前端音效]\n\n<Api name=\"ReportFrontendAudioEvent\">\n  id / volume / speed。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      CReference* ReportFrontendAudioEvent(int id, float volume, float speed);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      AudioEngine.ReportFrontendAudioEvent(id, 0.0f, 1.0f);\n      // id 见游戏音频事件表 / eAudioEvents 相关\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 任务音频事件 [#任务音频事件]\n\n<Api name=\"ReportMissionAudioEvent\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void ReportMissionAudioEvent(eAudioEvents audioEvent, CVector const* coords);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CVector p = ped->GetPosition();\n      AudioEngine.ReportMissionAudioEvent(eventId, &p);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 音量 [#音量]\n\n<Api name=\"SetEffectsMasterVolume / SetMusicMasterVolume\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void SetEffectsMasterVolume(char volume);\n      void SetMusicMasterVolume(char volume);\n      void SetMusicFaderScalingFactor(float value);\n      void SetEffectsFaderScalingFactor(float value);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // AudioEngine.SetEffectsMasterVolume(vol);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 电台 [#电台]\n\n<Api name=\"StartRadio / StopRadio / GetCurrentRadioStationID\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void StartRadio(int radioStation, char arg);\n      void StopRadio(tVehicleAudioSettings* settings, bool arg);\n      void RetuneRadio(char stationId);\n      char GetCurrentRadioStationID();\n      bool IsRadioOn();\n      bool IsVehicleRadioActive();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      char st = AudioEngine.GetCurrentRadioStationID();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 状态查询 [#状态查询]\n\n<Api name=\"IsLoadingTuneActive / IsRadioRetuneInProgress\">\n  ```cpp\n  bool IsLoadingTuneActive();\n  bool IsRadioRetuneInProgress();\n  bool IsAmbienceTrackActive();\n  ```\n</Api>\n\n## 注意 [#注意]\n\n| 点    | 说明                                        |\n| ---- | ----------------------------------------- |\n| 简单音效 | 也可用 [Utils 音频](/docs/plugins/utils/audio) |\n| 底层   | `CAE*` 管理器众多，按需查头文件                       |\n";
